-- Thumbnails are generated by our own step, later than the APOD itself.
-- The URL is built from config + date, so only "made at" is stored.
CREATE TABLE apod_thumbnail
(
    date         DATE                     NOT NULL,
    generated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (date),
    FOREIGN KEY (date) REFERENCES apod (date) ON DELETE CASCADE
);

-- Old YouTube/Vimeo/NASA links are not used any more.
ALTER TABLE apod
    DROP COLUMN thumbnail_url;